import{_ as t,o as s,c as a,ag as o}from"./chunks/framework.C9sp7nFj.js";const m=JSON.parse('{"title":"Skills & rules","description":"","frontmatter":{},"headers":[],"relativePath":"kit/skills-and-rules.md","filePath":"kit/skills-and-rules.md"}'),r={name:"kit/skills-and-rules.md"};function n(l,e,i,d,c,u){return s(),a("div",null,[...e[0]||(e[0]=[o('<h1 id="skills-rules" tabindex="-1">Skills &amp; rules <a class="header-anchor" href="#skills-rules" aria-label="Permalink to &quot;Skills &amp; rules&quot;">​</a></h1><p>FewUI is designed for <strong>Cursor rules</strong> and <strong>agent skills</strong> alongside code.</p><h2 id="cursor-rules-mdc" tabindex="-1">Cursor rules (<code>.mdc</code>) <a class="header-anchor" href="#cursor-rules-mdc" aria-label="Permalink to &quot;Cursor rules (`.mdc`)&quot;">​</a></h2><p>Rules encode non-negotiables:</p><ul><li>Use <code>ui-*</code> components; do not override with arbitrary classes on components.</li><li>i18n for all user-visible strings.</li><li>API access through the app request layer.</li></ul><p>Generate a starter rule from the playground: <strong>Download rules</strong> → <code>fewui-theme.mdc</code>.</p><h2 id="agent-skills-skill-md" tabindex="-1">Agent skills (<code>SKILL.md</code>) <a class="header-anchor" href="#agent-skills-skill-md" aria-label="Permalink to &quot;Agent skills (`SKILL.md`)&quot;">​</a></h2><p>Skills tell agents <em>when</em> and <em>how</em> to use Kit:</p><ul><li>Component choice for forms, dialogs, lists.</li><li>Theme token reference for the current project.</li><li>Links to Kit docs and playground.</li></ul><p>Generate from the playground: <strong>Download skill</strong>.</p><h2 id="component-data-for-agents" tabindex="-1">Component data for agents <a class="header-anchor" href="#component-data-for-agents" aria-label="Permalink to &quot;Component data for agents&quot;">​</a></h2><p><code>fewui/components.json</code> lists every component with props (type, default, description), events and slots. It is generated from the source on every build, so an agent can check a prop name or an allowed value instead of guessing. The same data backs the <a href="./components/">component pages</a>; <code>llms.txt</code> at the site root indexes them.</p><h2 id="restta-reference" tabindex="-1">Restta reference <a class="header-anchor" href="#restta-reference" aria-label="Permalink to &quot;Restta reference&quot;">​</a></h2><p>The Restta frontend and landing apps implement these patterns in production. Use them as examples when extending Kit.</p>',14)])])}const h=t(r,[["render",n]]);export{m as __pageData,h as default};
